// Run against an isolated test server; fixtures are generated by the backend Builder.
const { chromium } = require("playwright");
const fs = require("node:fs");
const path = require("node:path");
const assert = require("node:assert/strict");

(async () => {
  const browser = await chromium.launch({executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH});
  try {
    for (const [kind, filename] of [["rpi_pico", "pico.uf2"], ["rpi_pico2", "pico2.uf2"], ["esp32_devkitc", "esp32.bin"]]) {
      const page = await browser.newPage({viewport: {width: 1440, height: 1000}});
      const errors = [];
      page.on("pageerror", error => errors.push(String(error)));
      await page.goto(process.env.BASE + "/#simulator");
      const projects = process.env.FIRMWARE_PROJECTS || path.join(__dirname, "fixtures/firmware");
      const fixtures = process.env.FIRMWARE_FIXTURES || path.join(__dirname, "../../backend/tests/fixtures/firmware");
      const schematic = JSON.parse(fs.readFileSync(path.join(projects, kind + ".json"), "utf8"));
      await page.evaluate(s => localStorage.setItem("circuitos.schematic", JSON.stringify(s)), schematic);
      await page.reload();
      const picker = page.getByRole("combobox", {name: "Selecionar componente", exact: true});
      await picker.selectOption("c1");
      const upload = page.getByLabel(/Carregar firmware da IDE/);
      await upload.setInputFiles(path.join(fixtures, filename));
      await page.getByText("Firmware compilado", {exact: true}).waitFor();
      await upload.setInputFiles({name: "invalid." + filename.split(".").pop(), mimeType: "application/octet-stream", buffer: Buffer.from("invalid")});
      await page.locator(".properties [role=alert]").waitFor();
      assert.equal(await page.getByText(filename, {exact: true}).count(), 1);
      const response = page.waitForResponse(r => r.url().endsWith("/schematic/simulate") && r.request().method() === "POST");
      await page.getByRole("button", {name: "Simular", exact: true}).click();
      const jobId = (await (await response).json()).job_id;
      let job;
      const deadline = Date.now() + 240000;
      do {
        await page.waitForTimeout(500);
        job = await (await page.request.get(process.env.BASE + "/api/v1/simulations/" + jobId)).json();
        if (Date.now() > deadline) throw Error("Simulation timed out: " + kind);
      } while (!["done", "failed"].includes(job.state));
      assert.equal(job.state, "done", JSON.stringify(job.error));
      assert.ok(job.summary.cosim.serial.U1.some(row => /204[78]$/.test(row[1])));
      await page.screenshot({path: path.join(process.env.SHOTS, kind + ".png")});
      await page.reload();
      await picker.selectOption("c1");
      await page.getByText("Firmware compilado", {exact: true}).waitFor();
      await page.getByRole("button", {name: "Retirar firmware e usar código-fonte"}).click();
      await page.getByText("Código-fonte interpretado", {exact: true}).waitFor();
      assert.deepEqual(errors, []);
      console.log(kind + ": upload, invalid-file preservation, simulation, persistence, removal passed");
      await page.close();
    }
  } finally { await browser.close(); }
})().catch(error => {console.error(error); process.exit(1);});
